def read_user_file(filename):
    base_dir = os.path.abspath("/var/app/uploads")
    path = os.path.abspath(os.path.join(base_dir, filename))
    if not path.startswith(base_dir):
        raise ValueError("Invalid filename")
    with open(path) as f:
        return f.read()
